                        {
                            <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                   checked="@(_theme == theme)" @onchange="() => _theme = theme" />
                            <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    <div class="btn-group" role="group">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <input type="radio" class="btn-check" name="fontSize" id="@($"size-{size}")"
                                   checked="@(_fontSize == size)" @onchange="() => _fontSize = size" />
                            <label class="btn btn-outline-secondary" for="@($"size-{size}")">@size</label>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;" @bind="_language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

                @if (_showSuccess)
                {
                    <div class="alert alert-success mt-3 alert-dismissible fade show" role="alert">
                        Appearance settings saved!
                        <button type="button" class="btn-close" @onclick="() => _showSuccess = false"></button>
                    </div>
                }
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h6>Sample Heading</h6>
                        <p class="@(_compactMode ? "mb-1" : "mb-3")">
                            This is a preview of how your content will look with the selected settings.
                        </p>
                        <button class="btn btn-sm btn-primary">Sample Button</button>
                        <div class="mt-2">
                            <span class="badge bg-secondary">@_theme Theme</span>
                            <span class="badge bg-info">@_fontSize</span>
                            <span class="badge bg-success">@GetLanguageName()</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_theme == "Dark") classes.Add("bg-dark text-white");
        if (_compactMode) classes.Add("p-2");
        else classes.Add("p-3");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var fontSize = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {fontSize};";
    }

    private string GetLanguageName() => _language switch
    {
        "en" => "English",
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => _language
    };
}

