    margin: 2rem auto;
    padding: 0 1rem;
}

.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 600px;
}

.settings-sidebar {
    min-width: 200px;
    flex-shrink: 0;
}

.settings-sidebar .nav-link {
    text-align: left;
