    background-color: var(--bs-light);
}

.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--bs-border-color);
}

